head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gIndex;
scwin.gIsurCd;
scwin.gComAbbrv;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gParamObj = new Array(4);
scwin.gISUR_CD;
scwin.gCOM_NM;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.setCode();
        $c.cm.PanelToGroupBox(panel_5);
        $c.cm.PanelToGroupBox(panel_6);
        $c.cm.PanelToGroupBox(panel_2);
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        MxTab_1.setSelectedTabIndex("1");
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37220.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name MxTab_1_OnSelChanged
 * @description Mx Tab 1 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MxTab_1_OnSelChanged = async function(nIndex) {
    try {
        if (nIndex === '1') {
            $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
            scwin.gIndex = nIndex;
            await scwin.search();
        } else if (nIndex === '2') {
            $c.cm.fn_com_isur(txb_isur_cd2, txb_com_abbrv2);
            scwin.gIndex = nIndex;
            await scwin.search2();
        } else {
            scwin.gIndex = nIndex;
            await scwin.tab3Search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37220.MxTab_1_OnSelChanged" });
    }
};

/**
 * @method
 * @name cmb_DEP_CD_onselchange
 * @description cmb_DEP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DEP_CD_onselchange = function() {
    try {
        dts_EMP_NO.sort("DEP_CD", 0);
        // dts_EMP_NO.sort(); // W-Craft 주석처리
        dts_EMP_NO.UseFilter = true;
        dts_EMP_NO.Filter();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37220.cmb_DEP_CD_onselchange" });
    }
};

/**
 * @method
 * @name cmb_DEP_CD2_onselchange
 * @description cmb_DEP_CD2 onselchange 이벤트
