/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF37220.xml", SCREN_PROCS_TP_CD_07, '');
        if (scwin.gIndex === '1') {
            $c.data.downloadGridViewExcel(grd_Grid1, {fileName: "교육이수현황목록검색(상장법인)", type: "8"});
        } else if (scwin.gIndex === '2') {
            $c.data.downloadGridViewExcel(grd_Grid2, {fileName: "교육이수현황목록검색(지정자문인)", type: "8"});
        } else if (scwin.gIndex === '3') {
            $c.data.downloadGridViewExcel(grd_Grid3, {fileName: "교육일정목록검색", type: "8"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37220.btn_Excel_onclick" });
    }
};

