///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name readTab2
 * @description 작업해야함
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readTab2 = async function(GridID, row, colid) {
    // 작업해야함
    const objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..
    const CMD = "R";
    if (row < 1) return;

    // OPEN
    if (colid === "COM_NM") {
        // 상세화면
        let vISUR_CD = objDataID.getCellData(row, "ISUR_CD");
        const vCOM_NM = objDataID.getCellData(row, "COM_NM");
        const vSTKCERT_LIST_DD = objDataID.getCellData(row, "STKCERT_LIST_DD");
        let url = "/issueinfo/ULDSTF30606.gfm?";
        url += "ISUR_CD=" + vISUR_CD;
        url += "&COM_NM=" + vCOM_NM;
        url += "&STKCERT_LIST_DD=" + vSTKCERT_LIST_DD;
        url += "&SCREN_ID=" + "ULDSTF37220.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        if (await scwin.setParam(CMD, vISUR_CD, vCOM_NM, vSTKCERT_LIST_DD)) // formal arguments

        {
            // frame.CreateDialogFrame("child01", "/issueinfo/ULDSTF30606.gfm", "세부교육이수현황", 10, 10, 1000, 850, "window");
            $c.frame.path("../../").GWinOpen("child01", url, "세부교육이수현황", 10, 20, 990, 770, "");
        }
    }
};

/**
 * @method
 * @name setParam
 * @description child에 param을 넘긴다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) === "undefined") {
        await $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    const argv = scwin.setParam.arguments;
    const argc = scwin.setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (let i = 0; i < argc; i++) // actual arguments

    {
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};
